(2471179, 338495, 38032, '<td valign="top">The lighting and composition here are very affective.</td>', 'The lighting and composition here are very affective.', '2006-05-31 09:03:13.000000', NULL, 1),
(2471190, 338984, 38032, '<td valign="top">love the processing here as well as the subject, POV -and the sky</td>', 'love the processing here as well as the subject, POV -and the sky', '2006-05-31 09:06:24.000000', NULL, 1),
(2471193, 339875, 38032, '<td valign="top">Really interesting and a little uncomfortable - in a good way.</td>', 'Really interesting and a little uncomfortable - in a good way.', '2006-05-31 09:07:13.000000', NULL, 1),
(2471198, 339456, 38032, '<td valign="top">I really like the color here- All I can think about is CW rotation, however. 6</td>', 'I really like the color here- All I can think about is CW rotation, however. 6', '2006-05-31 09:09:09.000000', NULL, 1),
(2471204, 339888, 38032, '<td valign="top">Is this the Peter B Lewis Building? :)   It''s awesome!</td>', 'Is this the Peter B Lewis Building? :)   It''s awesome!', '2006-05-31 09:10:52.000000', NULL, 1),
