(2479894, 337932, 58906, '<td valign="top">Nice balance, composition and capture.  Well done!</td>', 'Nice balance, composition and capture.  Well done!', '2006-06-02 18:54:00.000000', NULL, 1),
(2479910, 339255, 58906, '<td valign="top">Excellent perspective, rhythum, and symetry.  A slight boost in contrast and saturation without losing detail may add to the dramatic impact.  I like this one.</td>', 'Excellent perspective, rhythum, and symetry.  A slight boost in contrast and saturation without losing detail may add to the dramatic impact.  I like this one.', '2006-06-02 19:00:06.000000', NULL, 1),
(2479913, 339557, 58906, '<td valign="top">Great job of using the natural trees and lines of the roof to guide the eye to the focal point of the dome.  Well done!</td>', 'Great job of using the natural trees and lines of the roof to guide the eye to the focal point of the dome.  Well done!', '2006-06-02 19:02:51.000000', NULL, 1),
(2479917, 338205, 58906, '<td valign="top">Interesting lines and nice lighting.  Well done.</td>', 'Interesting lines and nice lighting.  Well done.', '2006-06-02 19:05:14.000000', NULL, 1),
(2479947, 339006, 58906, '<td valign="top">With a person in this photo it is a nice ''personal'' memory of visiting an awesome architectural delight.  Without the person in the photo, every viewer could be the visitor taking it all in. Would be a 10 without the person.  With the person... still an 8</td>', 'With a person in this photo it is a nice ''personal'' memory of visiting an awesome architectural delight.  Without the person in the photo, every viewer could be the visitor taking it all in. Would be a 10 without the person.  With the person... still an 8', '2006-06-02 19:14:27.000000', NULL, 1),
(2479962, 338697, 40370, '<td valign="top">It''s probably bigger than it looks too. Little tight crop across the top.</td>', 'It''s probably bigger than it looks too. Little tight crop across the top.', '2006-06-02 19:20:48.000000', NULL, 1),
(2479965, 339883, 40370, '<td valign="top">The light on the dome really creates an unusual effect. I would love to see this with the modern day doo-dads (vent, etc) cloned out but that would be a lot of work.</td>', 'The light on the dome really creates an unusual effect. I would love to see this with the modern day doo-dads (vent, etc) cloned out but that would be a lot of work.', '2006-06-02 19:23:40.000000', NULL, 1),
(2479967, 339743, 40370, '<td valign="top">You''ve taken an ordinary building and made something special with the color adjustments.</td>', 'You''ve taken an ordinary building and made something special with the color adjustments.', '2006-06-02 19:24:54.000000', NULL, 1),
(2479968, 339338, 40370, '<td valign="top">Very unusual, red hot bricks.</td>', 'Very unusual, red hot bricks.', '2006-06-02 19:26:07.000000', NULL, 1);
