(2482378, 339544, 40370, '<td valign="top">Good choice of duotone, the reflection is essential to this image.</td>', 'Good choice of duotone, the reflection is essential to this image.', '2006-06-03 22:32:01.000000', NULL, 1),
(2482381, 339697, 40370, '<td valign="top">Very balanced image, appealing, but more interior design than actual structural design.</td>', 'Very balanced image, appealing, but more interior design than actual structural design.', '2006-06-03 22:35:11.000000', NULL, 1),
